<?php
require 'config.php'; wajib_admin();
$error=''; $ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  $judul=trim($_POST['judul']??''); $mk=trim($_POST['mata_kuliah']??''); $deskripsi=trim($_POST['deskripsi']??''); $deadline=$_POST['deadline']??'';
  if($judul===''||$mk===''||$deadline==='') $error='Judul, mata kuliah, dan deadline wajib diisi.';
  elseif(strtotime($deadline)===false) $error='Format deadline tidak valid.';
  else { $s=$pdo->prepare('INSERT INTO tugas (judul,mata_kuliah,deskripsi,deadline,created_by) VALUES (?,?,?,?,?)'); $s->execute([$judul,$mk,$deskripsi,str_replace('T',' ',$deadline).':00',$_SESSION['user']['id']]); $ok='Tugas berhasil ditambahkan.'; }
}
?>
